import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import { auditBoundaryProvenance } from "./boundary-audit.js";
import type { BoundaryException } from "./boundary-exceptions.js";

const directories: string[] = [];
const fixture = (source: string) => {
  const cwd = mkdtempSync(join(tmpdir(), "bundjil-boundary-audit-"));
  directories.push(cwd);
  const file = join(cwd, "fixture.ts");
  writeFileSync(file, source);
  return { cwd, file };
};

afterEach(() => {
  for (const directory of directories.splice(0)) rmSync(directory, { force: true, recursive: true });
});

describe("boundary provenance audit", () => {
  it("accepts decoded public contracts and Effectful codecs", () => {
    const { cwd, file } = fixture(`
      export declare const AccountId: { readonly Type: unique symbol };
      export type AccountId = typeof AccountId.Type;
      export interface Accounts { readonly find: (id: AccountId) => Promise<AccountId>; }
    `);
    expect(auditBoundaryProvenance({ cwd, files: [file] })).toEqual([]);
  });

  it.each([
    ["boundary-raw-primitive", "export interface Accounts { readonly find: (id: string) => Promise<void>; }"],
    ["direct-json", "export const decode = () => JSON.parse('{}');"],
    ["sync-schema-codec", "export const decode = () => Schema.decodeSync(Value);"],
    ["config-primitive", "export const token = Config.redacted('TOKEN');"],
    ["raw-fetch", "export const request = () => fetch('https://example.test');"],
    ["raw-response-text", "export const read = (response: Response) => response.text();"],
    ["unsafe-boundary-syntax", "export const id = value as string;"],
  ])("rejects %s", (rule, source) => {
    const { cwd, file } = fixture(source);
    expect(auditBoundaryProvenance({ cwd, files: [file] }).map((diagnostic) => diagnostic.rule)).toContain(rule);
  });

  it("admits one exact exception and rejects it when stale", () => {
    const { cwd, file } = fixture("export const request = () => fetch('https://example.test');");
    const exception: BoundaryException = {
      file: "fixture.ts",
      symbol: "request",
      owner: "@bundjil/example",
      boundaryKind: "provider",
      canonicalContract: "ExampleResponse",
      admittedSyntax: "global fetch",
      reason: "Fixture proves exact symbol matching.",
      rule: "raw-fetch",
    };
    expect(auditBoundaryProvenance({ cwd, files: [file], exceptions: [exception] })).toEqual([]);
    expect(auditBoundaryProvenance({ cwd, files: [file], exceptions: [{ ...exception, symbol: "other" }] })[0]?.message).toContain("Stale exception");
  });
});

export type BoundaryKind =
  | "cli"
  | "config"
  | "file"
  | "framework"
  | "http-in"
  | "http-out"
  | "persistence"
  | "provider";

export type BoundaryException = Readonly<{
  file: string;
  symbol: string;
  owner: string;
  boundaryKind: BoundaryKind;
  canonicalContract: string;
  admittedSyntax: string;
  reason: string;
  rule: BoundaryRule;
}>;

export type BoundaryRule =
  | "boundary-raw-primitive"
  | "config-primitive"
  | "direct-json"
  | "raw-fetch"
  | "raw-response-text"
  | "sync-schema-codec"
  | "unsafe-boundary-syntax";

/**
 * Temporary, symbol-level admissions for third-party/framework contracts.
 * Entries are deliberately removed by Tasks 2-4 as their owners migrate.
 */
export const boundaryExceptions: readonly BoundaryException[] = [];

import { readdirSync } from "node:fs";
import { relative, resolve, sep } from "node:path";
import ts from "typescript";

import {
  boundaryExceptions,
  type BoundaryException,
  type BoundaryRule,
} from "./boundary-exceptions.js";

export type BoundaryDiagnostic = Readonly<{
  file: string;
  line: number;
  rule: BoundaryRule;
  symbol: string;
  message: string;
}>;

type AuditOptions = Readonly<{
  cwd: string;
  files?: readonly string[];
  exceptions?: readonly BoundaryException[];
}>;

const productionFile = (file: string) =>
  /\.(?:[cm]?ts|tsx)$/.test(file) &&
  !file.includes(`${sep}test${sep}`) &&
  !file.endsWith(".test.ts") &&
  !file.includes(`${sep}node_modules${sep}`) &&
  !file.includes(`${sep}dist${sep}`);

const sourceFiles = (directory: string): readonly string[] =>
  readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const path = resolve(directory, entry.name);
    return entry.isDirectory() ? sourceFiles(path) : productionFile(path) ? [path] : [];
  });

const rootSourceFiles = (cwd: string) =>
  ["apps", "packages"].flatMap((directory) => sourceFiles(resolve(cwd, directory)));

const nodeSymbol = (node: ts.Node) => {
  let current: ts.Node | undefined = node;
  while (current !== undefined) {
    if (ts.isFunctionDeclaration(current) && current.name !== undefined) return current.name.text;
    if (ts.isVariableDeclaration(current) && ts.isIdentifier(current.name)) return current.name.text;
    if (ts.isMethodDeclaration(current) && ts.isIdentifier(current.name)) return current.name.text;
    if (ts.isClassDeclaration(current) && current.name !== undefined) return current.name.text;
    if (ts.isInterfaceDeclaration(current) || ts.isTypeAliasDeclaration(current)) return current.name.text;
    current = current.parent;
  }
  return "<module>";
};

const hasExportModifier = (node: ts.Node) =>
  ts.canHaveModifiers(node) &&
  ts.getModifiers(node)?.some((modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword) === true;

const isPublic = (node: ts.Node) => {
  let current: ts.Node | undefined = node;
  while (current !== undefined && !ts.isSourceFile(current)) {
    if (hasExportModifier(current)) return true;
    current = current.parent;
  }
  return false;
};

const dottedName = (expression: ts.Expression): string | undefined => {
  if (ts.isIdentifier(expression)) return expression.text;
  if (ts.isPropertyAccessExpression(expression)) {
    const left = dottedName(expression.expression);
    return left === undefined ? undefined : `${left}.${expression.name.text}`;
  }
  return undefined;
};

const typeContainsRawPrimitive = (node: ts.TypeNode): boolean => {
  if (
    node.kind === ts.SyntaxKind.StringKeyword ||
    node.kind === ts.SyntaxKind.UnknownKeyword ||
    node.kind === ts.SyntaxKind.AnyKeyword
  ) return true;
  if (ts.isTypeReferenceNode(node) && ts.isIdentifier(node.typeName)) {
    const first = node.typeArguments?.[0];
    return (node.typeName.text === "Record" || node.typeName.text === "Map") &&
      first !== undefined && first.kind === ts.SyntaxKind.StringKeyword;
  }
  return ts.forEachChild(node, typeContainsRawPrimitive) ?? false;
};

const exactException = (
  exception: BoundaryException,
  file: string,
  symbol: string,
  rule: BoundaryRule
) => exception.file === file && exception.symbol === symbol && exception.rule === rule;

/** Runs the narrow provenance audit without loading application runtime code. */
export const auditBoundaryProvenance = (options: AuditOptions): readonly BoundaryDiagnostic[] => {
  const files = options.files ?? rootSourceFiles(options.cwd);
  const program = ts.createProgram({
    rootNames: [...files],
    options: {
      module: ts.ModuleKind.NodeNext,
      moduleResolution: ts.ModuleResolutionKind.NodeNext,
      noEmit: true,
      strict: true,
      target: ts.ScriptTarget.ESNext,
    },
  });
  const checker = program.getTypeChecker();
  const exceptions = options.exceptions ?? boundaryExceptions;
  const diagnostics: BoundaryDiagnostic[] = [];
  const usedExceptions = new Set<BoundaryException>();

  const report = (node: ts.Node, rule: BoundaryRule, message: string) => {
    const sourceFile = node.getSourceFile();
    const file = relative(options.cwd, sourceFile.fileName);
    const symbol = nodeSymbol(node);
    const exception = exceptions.find((entry) => exactException(entry, file, symbol, rule));
    if (exception !== undefined) {
      usedExceptions.add(exception);
      return;
    }
    const line = sourceFile.getLineAndCharacterOfPosition(node.getStart(sourceFile)).line + 1;
    diagnostics.push({
      file,
      line,
      rule,
      symbol,
      message: `${message} Define or reuse an owner-named Schema contract, then decode at the inbound adapter or encode at the outbound adapter.`,
    });
  };

  for (const sourceFile of program.getSourceFiles()) {
    if (!files.includes(sourceFile.fileName)) continue;
    const visit = (node: ts.Node): void => {
      if (isPublic(node) && ts.isTypeNode(node) && typeContainsRawPrimitive(node)) {
        // Resolving the type ensures aliases and imports are inspected by the checker.
        checker.getTypeFromTypeNode(node);
        report(node, "boundary-raw-primitive", "Public boundary signatures cannot expose raw string, unknown, any, Record<string, ...>, or Map<string, ...>.");
      }
      if (ts.isCallExpression(node)) {
        const name = dottedName(node.expression);
        if (name === "JSON.parse" || name === "JSON.stringify") {
          report(node, "direct-json", "Direct JSON APIs bypass the canonical Schema codec.");
        }
        if (
          name === "Schema.decodeSync" || name === "Schema.decodeUnknownSync" ||
          name === "Schema.encodeSync" || name === "Schema.encodeUnknownSync"
        ) {
          report(node, "sync-schema-codec", "Production and operator boundaries must use Effectful Schema codecs.");
        }
        if (
          name === "Config.string" || name === "Config.nonEmptyString" || name === "Config.redacted"
        ) {
          report(node, "config-primitive", "Semantic configuration must use Config.schema with its owner-named Schema.");
        }
        if (name === "fetch") report(node, "raw-fetch", "Provider fetch must be confined to a named adapter using Effect HttpClient.");
        if (name?.endsWith(".text") === true || name?.endsWith(".json") === true) {
          report(node, "raw-response-text", "Raw response text or JSON must be decoded by the canonical boundary codec before domain use.");
        }
      }
      if (ts.isAsExpression(node) || ts.isTypeAssertionExpression(node) || ts.isNonNullExpression(node)) {
        report(node, "unsafe-boundary-syntax", "Unsafe assertions and non-null assertions are not admitted at a boundary.");
      }
      ts.forEachChild(node, visit);
    };
    visit(sourceFile);
  }

  for (const exception of exceptions) {
    if (!usedExceptions.has(exception)) {
      diagnostics.push({
        file: exception.file,
        line: 1,
        rule: exception.rule,
        symbol: exception.symbol,
        message: `Stale exception for ${exception.symbol}. Remove it or restore the exact third-party/framework boundary it documents.`,
      });
    }
  }
  return diagnostics.sort((left, right) => left.file.localeCompare(right.file) || left.line - right.line);
};

if (import.meta.main) {
  const diagnostics = auditBoundaryProvenance({ cwd: process.cwd() });
  if (diagnostics.length > 0) {
    for (const diagnostic of diagnostics) {
      console.error(`${diagnostic.file}:${diagnostic.line} [${diagnostic.rule}] ${diagnostic.symbol}: ${diagnostic.message}`);
    }
    process.exitCode = 1;
  }
}

