const codecMisuse = (checker: ts.TypeChecker, node: ts.CallExpression) => {
  if (!ts.isCallExpression(node.expression) || node.arguments.length !== 1) return undefined;
  const factoryName = dottedName(node.expression.expression);
  if (factoryName !== "Schema.decodeUnknownEffect" && factoryName !== "Schema.encodeUnknownEffect") return undefined;
  const codec = node.expression.arguments[0];
  const input = node.arguments[0];
  if (codec === undefined || input === undefined) return undefined;
  const expectedSide = factoryName === "Schema.decodeUnknownEffect" ? "Encoded" : "Type";
  const expected = codecSide(checker, codec, expectedSide);
  if (expected === undefined) return undefined;
