  const inputAnnotation = ts.isIdentifier(input)
    ? checker.getSymbolAtLocation(input)?.declarations?.find(ts.isVariableDeclaration)?.type
    : undefined;
  const annotationSide = inputAnnotation !== undefined && ts.isIndexedAccessTypeNode(inputAnnotation)
    ? inputAnnotation.indexType.getText().replaceAll(/["']/g, "")
    : undefined;
  return annotationSide === expectedSide && checker.isTypeAssignableTo(inputType, expected)
    ? expectedSide
